package com.codeguardian.service.ai.config; import com.codeguardian.config.AIConfigProperties; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Component; @Component @RequiredArgsConstructor public class AIModelConfigManager{private final AIConfigProperties props;public ModelProviderConfig getConfig(String name){String provider=(name==null||name.isBlank()?props.getProvider():name).toUpperCase();var c=props.getProviderConfig(provider);return ModelProviderConfig.builder().providerName(provider).baseUrl(c==null?null:c.getBaseUrl()).apiKey(c==null?null:c.getApiKey()).defaultModel(c==null?null:c.getModel()).enabled(c!=null&&Boolean.TRUE.equals(c.getEnabled())).timeout(props.getTimeout()).build();}}
